import {
  PROFESSIONS,
  SKILL_ROLES,
  getSkill,
  skillRoles,
  type ProfessionId,
  type SkillRole,
} from "@vibewars/game-core";

import { SKILL_BAR_SLOTS, equippableSkills, validateBuild } from "../storage/build-validation.js";
import {
  TEAM_SCHEMA_VERSION,
  type StoredTeam,
  type TeamCharacter,
  type TeamBuildSize,
} from "../storage/schema.js";

/**
 * The team builder (brief §18, §4).
 *
 * Teams are first-class. Each has a size, 2, 4 or 8, fixed when it is
 * made (#2109), and always exactly that many members (#2225): a member is
 * replaced, never added or taken off. Each member is a character of the
 * team's own (#1452): one copied from a Solo character is a copy, and
 * editing either leaves the other alone.
 */

/** A team of `members`, which must be `size` of them. */
export function teamOf(
  id: string,
  size: TeamBuildSize,
  members: readonly TeamCharacter[],
): StoredTeam {
  return {
    schemaVersion: TEAM_SCHEMA_VERSION,
    id,
    name: "New Team",
    size,
    members: members.map((character) => ({ character })),
    rulesetId: "minimal-gw-inspired-pvp-v1",
    updatedAt: Date.now(),
  };
}

/** A new team: `size` blank members (#2225), each what `blank` makes. */
export function newTeam(id: string, size: TeamBuildSize, blank: () => TeamCharacter): StoredTeam {
  return teamOf(
    id,
    size,
    Array.from({ length: size }, () => blank()),
  );
}

/**
 * `character` as a team member under `id`: its build only, copied, so a
 * later edit to either is not seen by the other.
 */
export function teamCharacter(character: TeamCharacter, id: string): TeamCharacter {
  return {
    id,
    name: character.name,
    primaryProfession: character.primaryProfession,
    secondaryProfession: character.secondaryProfession,
    attributes: character.attributes.map((a) => ({ attributeId: a.attributeId, rank: a.rank })),
    skillBar: [...character.skillBar],
    equipment: character.equipment,
  };
}

/** The team with the member whose id is `character.id` replaced by `character`. */
export function replaceMember(team: StoredTeam, character: TeamCharacter): StoredTeam {
  return {
    ...team,
    members: team.members.map((member) =>
      member.character.id === character.id ? { character } : member,
    ),
    updatedAt: Date.now(),
  };
}

/**
 * Move a member one position toward the front or back.
 *
 * Order matters to players (it is the slot order they will see in the
 * lobby), so reordering is a first-class operation rather than
 * delete-and-re-add, which would lose the member's place entirely.
 */
export function moveMember(team: StoredTeam, index: number, delta: number): StoredTeam {
  const target = index + delta;
  if (index < 0 || index >= team.members.length || target < 0 || target >= team.members.length) {
    return team;
  }
  const members = [...team.members];
  const moved = members[index];
  const displaced = members[target];
  if (moved === undefined || displaced === undefined) {
    return team;
  }
  members[index] = displaced;
  members[target] = moved;
  return { ...team, members, updatedAt: Date.now() };
}

export interface TeamProblem {
  readonly message: string;
}

/**
 * Validate a team (brief §24): its name, its size, and each member's
 * build by the same rules a Solo character's is held to (#1452).
 */
export function validateTeam(team: StoredTeam): TeamProblem[] {
  const problems: TeamProblem[] = [];

  if (team.name.trim() === "") {
    problems.push({ message: "team name must not be empty" });
  }
  if (team.members.length !== team.size) {
    problems.push({
      message: `a team of ${String(team.size)} has ${String(team.size)} members, not ${String(team.members.length)}`,
    });
  }

  team.members.forEach(({ character }, index) => {
    if (validateBuild(character).length > 0) {
      problems.push({
        message: `slot ${String(index + 1)}, ${character.name}, is not a legal build: open it to see why`,
      });
    }
  });

  return problems;
}

/** One slot of one member's bar, the member by its place on the team. */
export interface TeamSlot {
  readonly member: number;
  readonly slot: number;
}

/**
 * Why `skillId` may not go into `slot` of `member`'s bar (#2227), or
 * `undefined` when it may: by `equipSkill`'s rules, the skill already in
 * `slot` counting as gone. Unlike a library drop, another elite elsewhere
 * on the bar refuses it rather than giving way.
 */
export function slotRefusal(
  member: TeamCharacter,
  slot: number,
  skillId: string,
): string | undefined {
  const skill = getSkill(skillId);
  if (skill === undefined) {
    return "Not a skill in the game";
  }
  const others = member.skillBar.filter((id, index): id is string => index !== slot && id !== null);
  if (others.includes(skillId)) {
    return `${skill.name} is already on ${member.name}'s bar`;
  }
  if (!equippableSkills(member).some((each) => each.id === skillId)) {
    // As `professionLabel` says it: that module draws, and this one loads
    // in Node too, through `team-transfer.ts` (e2e).
    const { primaryProfession: primary, secondaryProfession: secondary } = member;
    const label =
      secondary === undefined
        ? PROFESSIONS[primary].name
        : `${PROFESSIONS[primary].name} / ${PROFESSIONS[secondary].name}`;
    return `${label} can't use ${skill.name}`;
  }
  const elite = skill.elite ? others.find((id) => getSkill(id)?.elite === true) : undefined;
  if (elite !== undefined) {
    return `${member.name} already has an elite, ${getSkill(elite)?.name ?? elite}`;
  }
  return undefined;
}

/**
 * `team` after a skill is dragged from one bar slot to another (#2227):
 * on one bar, the two slots trade places; onto another member's, it
 * moves there, trading places with what it lands on, or with `copy` (the
 * player held Shift) is copied there, the source keeping it. Every bar it
 * changes must stay legal by `slotRefusal`, else the problem, and the
 * team as it was.
 */
export function dragSkill(
  team: StoredTeam,
  from: TeamSlot,
  to: TeamSlot,
  copy: boolean,
): StoredTeam | TeamProblem {
  const source = team.members[from.member]?.character;
  const target = team.members[to.member]?.character;
  const skillId = source?.skillBar[from.slot] ?? null;
  if (source === undefined || target === undefined || skillId === null) {
    return { message: "nothing to drag" };
  }
  const withBar = (
    character: TeamCharacter,
    skillBar: readonly (string | null)[],
  ): TeamCharacter => ({ ...character, skillBar });
  const members = [...team.members];
  if (from.member === to.member) {
    if (from.slot === to.slot) {
      return team;
    }
    // A bar cannot hold a skill twice, so Shift onto its own bar moves.
    const skillBar = [...source.skillBar];
    skillBar[from.slot] = skillBar[to.slot] ?? null;
    skillBar[to.slot] = skillId;
    members[from.member] = { character: withBar(source, skillBar) };
    return { ...team, members, updatedAt: Date.now() };
  }
  const intoTarget = slotRefusal(target, to.slot, skillId);
  if (intoTarget !== undefined) {
    return { message: intoTarget };
  }
  const displaced = target.skillBar[to.slot] ?? null;
  if (!copy && displaced !== null) {
    const intoSource = slotRefusal(source, from.slot, displaced);
    if (intoSource !== undefined) {
      return { message: intoSource };
    }
  }
  const targetBar = [...target.skillBar];
  targetBar[to.slot] = skillId;
  members[to.member] = { character: withBar(target, targetBar) };
  if (!copy) {
    const sourceBar = [...source.skillBar];
    sourceBar[from.slot] = displaced;
    members[from.member] = { character: withBar(source, sourceBar) };
  }
  return { ...team, members, updatedAt: Date.now() };
}

/** "1 member", "4 members": a builds drawer row's (#2116), a full team's (#2109). */
export function memberCount(n: number): string {
  return `${String(n)} ${n === 1 ? "member" : "members"}`;
}

/** Duplicate a team under a new id, so the original is untouched, at its size. */
export function duplicateTeam(team: StoredTeam, newId: string): StoredTeam {
  return { ...team, id: newId, name: `${team.name} (copy)`, updatedAt: Date.now() };
}

/** One bar slot of one member: what a counter or a find-a-skill marks. */
export interface TeamCell {
  /** The member's `character.id`. */
  readonly characterId: string;
  readonly slot: number;
}

export type TeamCounterId = SkillRole | "energy" | "adrenaline" | "empty";

/** One counter above the team grid (#575), and the cells it counts. */
export interface TeamCounter {
  readonly id: TeamCounterId;
  readonly label: string;
  /** What it counts, for its tooltip. */
  readonly title: string;
  readonly cells: readonly TeamCell[];
  /** Whether a team with none of it lacks something: the counter turns amber. */
  readonly wanted: boolean;
}

const ROLE_COUNTERS: Readonly<Record<SkillRole, { label: string; title: string }>> = {
  interrupt: { label: "interrupts", title: "skills that interrupt a foe's skill" },
  healing: { label: "healing", title: "skills that heal" },
  removal: { label: "removal", title: "skills that remove a condition or a hex" },
  knockdown: { label: "knockdowns", title: "skills that knock a foe down" },
  hex: { label: "hexes", title: "skills that hex a foe" },
  condition: { label: "conditions", title: "skills that give a foe a condition" },
  defence: { label: "defence", title: "skills that raise armor or block" },
};

/**
 * What the team's bars hold, counted per copy (#575): the seven skill
 * roles, energy and adrenaline skills, and the empty slots.
 */
export function teamCounters(members: StoredTeam["members"]): TeamCounter[] {
  const cells = new Map<TeamCounterId, TeamCell[]>();
  const count = (id: TeamCounterId, cell: TeamCell): void => {
    const list = cells.get(id) ?? [];
    list.push(cell);
    cells.set(id, list);
  };
  for (const { character } of members) {
    for (let slot = 0; slot < SKILL_BAR_SLOTS; slot += 1) {
      const cell = { characterId: character.id, slot };
      const skillId = character.skillBar[slot] ?? null;
      if (skillId === null) {
        count("empty", cell);
        continue;
      }
      const skill = getSkill(skillId);
      if (skill === undefined) {
        continue;
      }
      if (skill.cost !== undefined) {
        count(skill.cost.kind, cell);
      }
      for (const role of skillRoles(skill)) {
        count(role, cell);
      }
    }
  }
  return [
    ...SKILL_ROLES.map((role) => ({
      id: role,
      ...ROLE_COUNTERS[role],
      cells: cells.get(role) ?? [],
      wanted: true,
    })),
    {
      id: "energy",
      label: "energy",
      title: "skills that cost energy",
      cells: cells.get("energy") ?? [],
      wanted: false,
    },
    {
      id: "adrenaline",
      label: "adrenaline",
      title: "skills that cost adrenaline",
      cells: cells.get("adrenaline") ?? [],
      wanted: false,
    },
    {
      id: "empty",
      label: "empty",
      title: "empty bar slots",
      cells: cells.get("empty") ?? [],
      wanted: false,
    },
  ];
}

/** How many of a team's characters share one pair of professions (#1785). */
export interface ProfessionMixEntry {
  readonly count: number;
  readonly primary: ProfessionId;
  readonly secondary: ProfessionId | undefined;
}

/** The team's professions, one entry per pair, most common first. */
export function professionMix(members: StoredTeam["members"]): ProfessionMixEntry[] {
  const entries = new Map<string, ProfessionMixEntry>();
  for (const { character } of members) {
    const { primaryProfession: primary, secondaryProfession: secondary } = character;
    const key = `${primary}/${secondary ?? ""}`;
    const count = (entries.get(key)?.count ?? 0) + 1;
    entries.set(key, { count, primary, secondary });
  }
  return [...entries.values()].sort((a, b) => b.count - a.count);
}
